// Fused SiLU(gate) * up.
__global__ void silu_mul_kernel(__half* out, const __half* gate, const __half* up, int n) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) {
        float g = __half2float(gate[i]);
        float s = g / (1.0f + expf(-g));
